<template><div class="login"><aside><div class="brand"><span class="brand-mark"><i></i><b></b></span><b>Pinggu Studio</b></div><div class="pitch"><small>INTELLIGENT WORKSPACE</small><h1>让专业判断<br>更快一步</h1><p>合同与招投标审查、知识问答与审计追踪，集中在一个清晰可靠的工作流中。</p></div><footer>© 2026 Pinggu Studio</footer></aside><main><div class="login-box"><div class="login-mark"><i></i><b></b></div><h2>登录工作室</h2><p>使用你的账户继续工作</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="handleLogin"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" :prefix-icon="User" placeholder="请输入用户名" size="large" /></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" :prefix-icon="Lock" type="password" show-password placeholder="请输入密码" size="large" @keyup.enter="handleLogin" /></el-form-item><el-button class="submit" type="primary" size="large" :loading="loading" @click="handleLogin">登录</el-button></el-form><small class="security">安全连接 · 演示账号 analyst / Analyst@123456</small></div></main></div></template>
<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { Lock, User } from '@element-plus/icons-vue'
import { authApi } from '@/api/auth'
import { useAuthStore } from '@/stores/auth'
const router = useRouter(); const auth = useAuthStore(); const formRef = ref<FormInstance>(); const loading = ref(false); const form = reactive({ username: '', password: '' }); const rules: FormRules = { username: [{ required: true, message: '请输入用户名', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function handleLogin() { if (!(await formRef.value?.validate().catch(() => false))) return; loading.value = true; try { const { data } = await authApi.login(form); auth.login(data.access_token, { userId: data.user_id, tenantId: data.tenant_id, username: data.username }); router.push('/studio') } catch { ElMessage.error('用户名或密码错误') } finally { loading.value = false } }
</script>
